-- =====================================================================
-- REBUILD TOTAL & SINKRONISASI RESIK TABEL MENU_DIET & MENU_KOMPONEN
-- Calorie Lab Database Master Rebuild (Zero Error & Offset-Free)
-- =====================================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 1. Buat / Perbarui Struktur Tabel menu_diet
CREATE TABLE IF NOT EXISTS `menu_diet` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `nama_menu` VARCHAR(120) NOT NULL,
  `waktu_makan` ENUM('pagi','siang','malam','camilan') NOT NULL,
  `kalori` INT NOT NULL,
  `berat_gram` INT DEFAULT NULL,
  `takaran_saji` VARCHAR(255) DEFAULT NULL,
  `harga` INT NOT NULL DEFAULT 0,
  `vegetarian` TINYINT(1) NOT NULL DEFAULT 0,
  `deskripsi` TEXT DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tambah kolom jika tabel sudah ada tapi belum punya kolom berat_gram / takaran_saji
SET @col_b = (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'menu_diet' AND COLUMN_NAME = 'berat_gram');
SET @sql_b = IF(@col_b = 0, 'ALTER TABLE `menu_diet` ADD COLUMN `berat_gram` INT DEFAULT NULL AFTER `kalori`', 'SELECT 1');
PREPARE stmt_b FROM @sql_b; EXECUTE stmt_b; DEALLOCATE PREPARE stmt_b;

SET @col_t = (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'menu_diet' AND COLUMN_NAME = 'takaran_saji');
SET @sql_t = IF(@col_t = 0, 'ALTER TABLE `menu_diet` ADD COLUMN `takaran_saji` VARCHAR(255) DEFAULT NULL AFTER `berat_gram`', 'SELECT 1');
PREPARE stmt_t FROM @sql_t; EXECUTE stmt_t; DEALLOCATE PREPARE stmt_t;

-- 2. Buat Tabel menu_komponen
CREATE TABLE IF NOT EXISTS `menu_komponen` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `menu_id` INT NOT NULL,
  `nama_komponen` VARCHAR(150) NOT NULL,
  `takaran` VARCHAR(100) NOT NULL,
  `berat_gram` DECIMAL(6,1) NOT NULL DEFAULT 0.0,
  `kondisi` VARCHAR(100) DEFAULT NULL,
  `kalori_per_100g` DECIMAL(6,1) NOT NULL DEFAULT 0.0,
  `kalori_komponen` DECIMAL(6,1) NOT NULL DEFAULT 0.0,
  `sumber` VARCHAR(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_komponen_menu_id` (`menu_id`),
  CONSTRAINT `fk_komponen_menu_diet` FOREIGN KEY (`menu_id`) REFERENCES `menu_diet` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 3. Bersihkan data lama agar fresh dan bersih 100%
TRUNCATE TABLE `menu_komponen`;
TRUNCATE TABLE `menu_kategori`;
TRUNCATE TABLE `menu_diet`;

